keyframes.cssText:
@keyframes phone-tap { 
  0% { transform: perspective(500px) translateY(12px) rotateX(0deg); }
  50% { transform: perspective(500px) translateY(12px) rotateX(48deg) scale(0.9); }
  100% { transform: perspective(500px) translateY(12px) rotateX(0deg); }
}

@keyframes border-rest { 
  0% { transform: scale(1); }
  50% { transform: scale(1.05); }
  100% { transform: scale(1); }
}

@keyframes phone-shimmer { 
  0% { transform: skewY(40deg) translateY(-66px); }
  50% { transform: skewY(40deg) translateY(10px); }
  100% { transform: skewY(40deg) translateY(-66px); }
}

@keyframes loadChatBubble { 
  0% { opacity: 0; transform: translateY(30px) scale(0.5); }
  100% { opacity: 1; transform: translateY(0px) scale(1); }
}

@keyframes UniversalChatTypingBubbleBounce { 
  0%, 100% { animation-timing-function: ease-out; transform: translateY(2px); }
  50% { animation-timing-function: ease-in-out; transform: translateY(-2.5px); }
}

@keyframes loadChatBox { 
  0% { opacity: 0; transform: translateY(30px) scale(0.5); }
  100% { opacity: 1; transform: translateY(0px) scale(1); }
}

@keyframes UniversalChatTypingBubbleBounce { 
  0%, 100% { animation-timing-function: ease-out; transform: translateY(2px); }
  50% { animation-timing-function: ease-in-out; transform: translateY(-2.5px); }
}

@keyframes loadInChatTreatment { 
  0% { opacity: 0; transform: scale(0.8) translateY(100%); }
  100% { opacity: 1; transform: scale(1) translateY(0px); }
}

@keyframes fadeIn { 
  0% { opacity: 0; transform: scale(0.5) translateY(50%); }
  100% { opacity: 1; transform: scale(1) translateY(0px); }
}

@keyframes pulse { 
  0% { transform: translateY(-50%) scale(1); }
  25% { transform: translateY(-50%) scale(2); }
  50% { transform: translateY(-50%) scale(1); }
  100% { transform: translateY(-50%) scale(1); }
}
